<?php
namespace App\Domain\AI\Knowledge\Retrieval;use App\Domain\AI\Agents\Models\AgentVersion;use App\Domain\AI\Knowledge\Contracts\KnowledgeRetriever;use App\Domain\AI\Knowledge\Data\{KnowledgeSearchMatch,KnowledgeSearchQuery};use App\Domain\AI\Knowledge\Enums\{KnowledgeIndexStatus,KnowledgeSourceStatus};use App\Domain\AI\Knowledge\Models\{AgentVersionKnowledgeSource,KnowledgeChunk};use App\Domain\AI\Tenancy\AiTenantBoundary;
final class LexicalKnowledgeRetriever implements KnowledgeRetriever
{
 public function __construct(private AiTenantBoundary$tenants){}
 public function retrieve(AgentVersion$agentVersion,KnowledgeSearchQuery$query):array{$this->tenants->assertResourceBelongsToCurrentTenant($agentVersion);$links=AgentVersionKnowledgeSource::query()->where('agent_version_id',$agentVersion->id)->get();if($links->isEmpty())return[];$versionIds=$links->pluck('knowledge_source_version_id');$chunks=KnowledgeChunk::query()->whereIn('knowledge_source_version_id',$versionIds)->whereHas('index',fn($q)=>$q->where('status',KnowledgeIndexStatus::Ready->value))->whereHas('source',fn($q)=>$q->where('status',KnowledgeSourceStatus::Active->value))->with(['index','source','knowledgeVersion'])->orderBy('knowledge_source_version_id')->orderBy('sequence')->limit(200)->get();$queryText=$this->normalize($query->value);$queryTerms=$this->terms($queryText);$matches=[];foreach($chunks as$chunk){if(!hash_equals($chunk->index->content_checksum,$chunk->knowledgeVersion->checksum)||(int)$chunk->index->knowledge_source_id!==(int)$chunk->source->id)continue;$text=$this->normalize($chunk->content);$terms=$this->terms($text);$hits=count(array_intersect($queryTerms,$terms));$coverage=$queryTerms?($hits/count($queryTerms)):0;$phrase=$queryText!==''&&str_contains($text,$queryText)?1:0;$score=min(1,($phrase*.55)+($coverage*.4)+(min($hits,5)*.01));if($score<=0)continue;$matches[]=new KnowledgeSearchMatch($chunk->source->uuid,$chunk->source->name,$chunk->knowledgeVersion->version_number,$chunk->source->type->value,$this->locator($chunk->locator),mb_substr($chunk->content,0,400),round($score,4),$chunk->sequence,(int)$chunk->id);}usort($matches,fn($a,$b)=>$b->score<=>$a->score?:strcmp($a->sourceUuid,$b->sourceUuid)?:$a->sequence<=>$b->sequence);return array_slice($matches,0,$query->topK);}
 private function normalize(string$value):string{$value=mb_strtolower($value,'UTF-8');return trim(preg_replace('/\s+/u',' ',preg_replace('/[^\pL\pN\s]+/u',' ',$value)??$value)??$value);}private function terms(string$value):array{return array_values(array_unique(preg_split('/\s+/u',$value,-1,PREG_SPLIT_NO_EMPTY)?:[]));}private function locator(array$locator):string{return($locator['kind']??null)==='faq'?'Pregunta frecuente '.(int)($locator['faq_number']??0).', parte '.(int)($locator['part']??1):'Sección '.(int)($locator['section']??1).', parte '.(int)($locator['part']??1);}
}
